# Find properties with remote check-in enabled
properties = model.search([('remote_checkin_enabled', '=', True)])

for property_rec in properties:
    try:
        property_rec.action_send_remote_checkin_links()
    except Exception as e:
        import logging
        _logger = logging.getLogger(__name__)
        _logger.error("Error generating remote check-in links for property %s: %s", property_rec.name, str(e))

# Sync reference tables monthly for all properties properties = env['pms.property'].search([('it_guest_registration_enabled', '=', True)])
for property_rec in properties: try: # Find or create table manager table_manager = model.search([('property_id', '=', property_rec.id)], limit=1) if not table_manager: table_manager = model.create({'property_id': property_rec.id})
# Only sync if last sync was more than 30 days ago or never synced from datetime import timedelta if (not table_manager.last_sync_date or table_manager.last_sync_date < (fields.Datetime.now() - timedelta(days=30))): table_manager.action_sync_all_tables()
except Exception as e: import logging _logger = logging.getLogger(__name__) _logger.error("Error syncing tables for property %s: %s", property_rec.name, str(e))
